```matlab
% 定义二维正态分布的PDF函数
function f = pdf_2d_normal(x, y, mu, Sigma)
    X = [x; y];
    f = 1 / (2*pi*sqrt(det(Sigma))) * exp(-0.5 * (X-mu)' * inv(Sigma) * (X-mu));
end

% 主程序
clear all; close all;

% 定义均值向量
mu = [0; 0];

% 定义四个协方差矩阵
Sigma1 = [2 0; 0 2];
Sigma2 = [2 0; 0 4];
Sigma3 = [2 1; 1 6];
Sigma4 = [2 3; 3 6];

% 创建网格点
[X, Y] = meshgrid(-3:0.1:3, -3:0.1:3);

% 计算每个协方差矩阵对应的PDF
Z1 = zeros(size(X));
Z2 = zeros(size(X));
Z3 = zeros(size(X));
Z4 = zeros(size(X));

for i = 1:size(X, 1)
    for j = 1:size(X, 2)
        Z1(i,j) = pdf_2d_normal(X(i,j), Y(i,j), mu, Sigma1);
        Z2(i,j) = pdf_2d_normal(X(i,j), Y(i,j), mu, Sigma2);
        Z3(i,j) = pdf_2d_normal(X(i,j), Y(i,j), mu, Sigma3);
        Z4(i,j) = pdf_2d_normal(X(i,j), Y(i,j), mu, Sigma4);
    end
end

% 绘制四个PDF曲面
figure;
subplot(2,2,1); surf(X, Y, Z1); title('\Sigma = [2 0; 0 2]');
subplot(2,2,2); surf(X, Y, Z2); title('\Sigma = [2 0; 0 4]');
subplot(2,2,3); surf(X, Y, Z3); title('\Sigma = [2 1; 1 6]');
subplot(2,2,4); surf(X, Y, Z4); title('\Sigma = [2 3; 3 6]');

% 绘制f(xa,xb=0), f(xa,xb=1), f(xa,xb=2)的曲线
figure;
xa = -3:0.1:3;
for i = 1:4
    subplot(2,2,i);
    eval(['Sigma = Sigma' num2str(i) ';']);
    plot(xa, pdf_2d_normal(xa, 0*xa, mu, Sigma), 'r', ...
         xa, pdf_2d_normal(xa, 1+0*xa, mu, Sigma), 'g', ...
         xa, pdf_2d_normal(xa, 2+0*xa, mu, Sigma), 'b');
    title(['\Sigma = ' mat2str(Sigma)]);
    legend('xb = 0', 'xb = 1', 'xb = 2');
end

% 绘制f(xa|xb=0), f(xa|xb=1), f(xa|xb=2)的曲线
figure;
for i = 1:4
    subplot(2,2,i);
    eval(['Sigma = Sigma' num2str(i) ';']);

    % 计算条件分布的参数
    mu_a = mu(1);
    sigma_a = Sigma(1,1);
    sigma_b = Sigma(2,2);
    rho = Sigma(1,2) / sqrt(sigma_a * sigma_b);

    for xb = 0:2
        mu_cond = mu_a + rho * sqrt(sigma_a/sigma_b) * (xb - mu(2));
        sigma_cond = sigma_a * (1 - rho^2);

        y = normpdf(xa, mu_cond, sqrt(sigma_cond));
        plot(xa, y); hold on;
    end

    title(['\Sigma = ' mat2str(Sigma)]);
    legend('xb = 0', 'xb = 1', 'xb = 2');
    hold off;
end

% 绘制f(x) = h的等高线
h_values = [0.02, 0.14];
figure;
for i = 1:4
    subplot(2,2,i);
    eval(['Sigma = Sigma' num2str(i) ';']);

    for h = h_values
        [C, h] = contour(X, Y, eval(['Z' num2str(i)]), [h h]);
        clabel(C, h);
        hold on;
    end

    title(['\Sigma = ' mat2str(Sigma)]);
    hold off;
end

% 计算相关系数
rho1 = Sigma1(1,2) / sqrt(Sigma1(1,1) * Sigma1(2,2));
rho2 = Sigma2(1,2) / sqrt(Sigma2(1,1) * Sigma2(2,2));
rho3 = Sigma3(1,2) / sqrt(Sigma3(1,1) * Sigma3(2,2));
rho4 = Sigma4(1,2) / sqrt(Sigma4(1,1) * Sigma4(2,2));

disp('相关系数:');
disp(['Sigma1: ' num2str(rho1)]);
disp(['Sigma2: ' num2str(rho2)]);
disp(['Sigma3: ' num2str(rho3)]);
disp(['Sigma4: ' num2str(rho4)]);
```

这段代码完成了以下任务：

1. 定义了二维正态分布的PDF函数。
2. 绘制了四个不同协方差矩阵对应的PDF曲面。
3. 绘制了f(xa,xb=0), f(xa,xb=1), f(xa,xb=2)的曲线。
4. 绘制了f(xa|xb=0), f(xa|xb=1), f(xa|xb=2)的条件概率密度曲线。
5. 绘制了f(x) = h的等高线，其中h取0.02和0.14。
6. 计算并显示了每个协方差矩阵对应的相关系数。

运行这段代码后，您将得到多个图形窗口，展示了不同的可视化结果。同时，在命令窗口中会显示计算得到的相关系数。

注意：这段代码假设您使用的是较新版本的MATLAB。如果您使用的是旧版本，可能需要对某些函数调用进行微调。

